mapper.select:
SELECT target_user_id
FROM match_center.user_swipe_history
WHERE deleted = 0
  AND user_id = #{userId}
  AND direction IN (2, 3)
  AND swiped_at >= #{since}
ORDER BY swiped_at DESC
LIMIT #{limit}

SELECT target_user_id
FROM match_center.user_swipe_history
WHERE deleted = 0
  AND user_id = #{userId}
ORDER BY swiped_at DESC
LIMIT #{limit}

SELECT COUNT(1)
FROM match_center.user_swipe_history
WHERE deleted = 0
  AND user_id = #{userId}
  AND swiped_at >= #{start}
  AND swiped_at < #{end}

SELECT DISTINCT user_id
FROM match_center.user_swipe_history
WHERE deleted = 0
  AND swiped_at >= #{start}
  AND swiped_at < #{end}
LIMIT #{limit}
